<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue';
import {useRoute} from 'vue-router';
import type {AdminSummary,Kind,Page,Status,Visibility} from '../../../../shared/contracts';
import {adminApi,kindLabels,statusLabels,dateLabel,errorMessage,timeLabel,isToolboxResource,toolboxCategories} from '../api';
import AdminNav from '../components/AdminNav.vue';
const route=useRoute();
const result=ref<Page<AdminSummary>|null>(null),busy=ref(false),error=ref(''),page=ref(1),kind=ref<Kind|''>(''),status=ref<Status|''>(''),visibility=ref<Visibility|''>(''),includeDeleted=ref(false);
const toolboxOnly=ref(route.query.toolbox==='1'),toolboxCategory=ref('');
const items=computed(()=>{const source=result.value?.items||[];return toolboxOnly.value?source.filter(i=>isToolboxResource(i)&&(!toolboxCategory.value||i.category===toolboxCategory.value)):source;});
let sequence=0;
async function load(reset=false){if(reset)page.value=1;const current=++sequence;busy.value=true;error.value='';result.value=null;const actualKind=toolboxOnly.value?'resource':kind.value||undefined;try{const data=await adminApi.list({page:page.value,pageSize:20,kind:actualKind,status:status.value||undefined,visibility:visibility.value||undefined,includeDeleted:includeDeleted.value});if(current===sequence)result.value=data;}catch(e){if(current===sequence)error.value=errorMessage(e);}finally{if(current===sequence)busy.value=false;}}
async function turn(delta:number){page.value+=delta;await load();}
watch(()=>route.query.toolbox,value=>{toolboxOnly.value=value==='1';if(toolboxOnly.value)kind.value='resource';load(true);});
onMounted(()=>load());
</script>
<template><AdminNav/><header><span class="eyebrow">站主管理</span><h1>{{toolboxOnly?'AI 工具箱':'把记录慢慢整理好'}}</h1><p class="muted">{{toolboxOnly?'这里只显示固定分类内的资源。公开发布后才会进入 /toolbox。':'草稿和撤回的内容仅你可见。保存与发布是两个独立动作。'}}</p></header><section class="card"><form class="filters" @submit.prevent="load(true)"><label v-if="!toolboxOnly">内容类型<select v-model="kind"><option value="">全部类型</option><option v-for="(label,key) in kindLabels" :key="key" :value="key">{{label}}</option></select></label><label v-if="toolboxOnly">工具箱分类<select v-model="toolboxCategory"><option value="">全部工具箱分类</option><option v-for="item in toolboxCategories" :key="item" :value="item">{{item}}</option></select></label><label>发布状态<select v-model="status"><option value="">全部状态</option><option v-for="(label,key) in statusLabels" :key="key" :value="key">{{label}}</option></select></label><label>可见性<select v-model="visibility"><option value="">全部</option><option value="private">私密</option><option value="public">公开</option></select></label><label class="check"><input v-model="includeDeleted" type="checkbox">含软删除</label><button :disabled="busy">筛选</button><RouterLink v-if="toolboxOnly" to="/admin/contents/new?mode=toolbox">新建 Skill</RouterLink></form><p v-if="busy" role="status">正在读取内容…</p><div v-else-if="error" role="alert"><p class="error">{{error}}</p><button @click="load()">重新加载</button> <RouterLink to="/admin/login">重新登录</RouterLink></div><template v-else-if="result"><p class="muted">当前页显示 {{items.length}} 条 · 服务端返回 {{result.total}} 条 · 第 {{result.page}} 页</p><p v-if="!items.length" class="notice">{{toolboxOnly?'当前没有符合固定分类的 AI 工具箱内容。':'当前没有符合条件的内容。可以新建一份私密草稿。'}}</p><article v-for="item in items" :key="item.id"><div><span class="eyebrow">{{kindLabels[item.kind]}} {{isToolboxResource(item)?'· AI 工具箱':''}} {{item.isDemo?'· 合成样本':''}}</span><h2><RouterLink :to="`/admin/contents/${item.id}/edit`">{{item.title}}</RouterLink></h2><p>{{dateLabel(item.recordDate)}}</p><p class="muted">{{item.deletedAt?'已软删除':statusLabels[item.status]}} · {{!item.deletedAt&&item.status==='published'&&item.visibility==='public'?'所有访客可见':'仅站主可见'}} · 保存为{{item.visibility==='public'?'公开':'私密'}}<template v-if="item.category"> · {{item.category}}</template></p><small>最后保存 {{timeLabel(item.updatedAt)}}</small></div><div class="links"><RouterLink :to="`/admin/contents/${item.id}/edit`">{{item.deletedAt?'查看记录':'管理内容'}}</RouterLink><RouterLink :to="`/admin/contents/${item.id}/preview`">预览已保存内容</RouterLink></div></article><div class="pager"><button :disabled="page<=1" @click="turn(-1)">上一页</button><button :disabled="result.page*result.pageSize>=result.total" @click="turn(1)">下一页</button></div></template></section></template>
<style scoped>.filters{display:flex;flex-wrap:wrap;gap:14px;align-items:end}label{display:grid;gap:6px}.check{display:flex;align-items:center;padding:10px 0}article{display:flex;justify-content:space-between;gap:20px;border-top:1px solid var(--line);padding:24px 0}h2{margin:6px 0}article p{margin:6px 0}.links,.pager{display:flex;gap:16px;flex-wrap:wrap}.links{align-content:center;align-items:center}.links a{color:var(--accent)}small{color:var(--muted)}@media(max-width:640px){article{display:block}.links{margin-top:16px}.filters label{flex:1;min-width:110px}}</style>
